import{_ as t,o as r,c as n,ae as a}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-07-11","description":"","frontmatter":{"date":"2026-07-11T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-07-11-product.md","filePath":"daily/2026-07-11-product.md"}'),e={name:"daily/2026-07-11-product.md"};function s(i,o,p,g,l,h){return r(),n("div",null,[...o[0]||(o[0]=[a('<h1 id="产品发布-2026-07-11" tabindex="-1">产品发布 - 2026-07-11 <a class="header-anchor" href="#产品发布-2026-07-11" aria-label="Permalink to &quot;产品发布 - 2026-07-11&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态包括Notion 3.4版本更新带来的AI功能和新展示模式，Notion AI引入GPT-5.4模型提升长任务处理能力，Figma推出AI工具挑战Canva和Adobe，以及Notion扩展AI助手功能并发布新SDK版本。最值得关注的是OpenAI即将发布AI浏览器挑战谷歌Chrome，以及Notion AI功能的重大升级。</p><hr><h3 id="_1-notion-3-4更新的6个新特性全教程与指南" tabindex="-1">1. Notion 3.4更新的6个新特性全教程与指南 <a class="header-anchor" href="#_1-notion-3-4更新的6个新特性全教程与指南" aria-label="Permalink to &quot;1. Notion 3.4更新的6个新特性全教程与指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=VDwpfCSAu3I" target="_blank" rel="noreferrer">6 NEW Features in the Notion 3.4 Update | Full Tutorial &amp; Guide</a></p><p><strong>一句话摘要</strong>: Notion 3.4更新带来AI功能、新展示模式等多项新特性。</p><p><strong>能解决什么问题</strong>: 提高个人和团队的工作效率，优化信息管理和协作。</p><p><strong>产品应用</strong>: 适用于需要高效信息管理、协作和自动化任务处理的个人和团队。</p><p><strong>示例场景</strong>: 使用Notion AI自动生成会议纪要和行动列表。</p><hr><h3 id="_2-notion-ai更新及新特性" tabindex="-1">2. Notion AI更新及新特性 <a class="header-anchor" href="#_2-notion-ai更新及新特性" aria-label="Permalink to &quot;2. Notion AI更新及新特性&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features - Matthias Frank</a></p><p><strong>一句话摘要</strong>: Notion AI新增GPT-5.4模型，提升长任务处理能力。</p><p><strong>能解决什么问题</strong>: 解决复杂任务规划和执行中的自动化需求。</p><p><strong>产品应用</strong>: 适用于需要自动化处理大量数据和复杂项目的任务。</p><p><strong>示例场景</strong>: 自动化生成晨间简报或总结复杂项目讨论。</p><hr><h3 id="_3-figma发布新的ai工具-用于创建网站、应用原型和营销资产" tabindex="-1">3. Figma发布新的AI工具，用于创建网站、应用原型和营销资产 <a class="header-anchor" href="#_3-figma发布新的ai工具-用于创建网站、应用原型和营销资产" aria-label="Permalink to &quot;3. Figma发布新的AI工具，用于创建网站、应用原型和营销资产&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://techcrunch.com/2025/05/07/figma-releases-new-ai-powered-tools-for-creating-sites-app-prototypes-and-marketing-assets" target="_blank" rel="noreferrer">Figma releases new AI-powered tools for creating sites, app prototypes, and marketing assets | TechCrunch</a></p><p><strong>一句话摘要</strong>: Figma推出AI驱动的新功能，挑战Canva和Adobe等创意解决方案。</p><p><strong>能解决什么问题</strong>: 解决设计师和营销人员创建网站和营销资产的效率和便捷性问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过模板和AI生成内容快速创建网站和营销素材。</p><p><strong>示例场景</strong>: 设计师使用Figma Sites快速搭建并发布品牌网站。</p><hr><h3 id="_4-notion文档更新日志" tabindex="-1">4. Notion文档更新日志 <a class="header-anchor" href="#_4-notion文档更新日志" aria-label="Permalink to &quot;4. Notion文档更新日志&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://developers.notion.com/page/changelog" target="_blank" rel="noreferrer">Changelog - Notion Docs</a></p><p><strong>一句话摘要</strong>: Notion扩展AI助手功能并发布新SDK版本</p><p><strong>能解决什么问题</strong>: 提高AI助手与Notion数据库交互能力</p><p><strong>产品应用</strong>: 适用于需要AI助手与Notion数据库协同工作的业务场景</p><p><strong>示例场景</strong>: 企业团队使用AI助手直接查询Notion数据库</p><hr><h3 id="_5-openai将发布ai浏览器挑战谷歌chrome" tabindex="-1">5. OpenAI将发布AI浏览器挑战谷歌Chrome <a class="header-anchor" href="#_5-openai将发布ai浏览器挑战谷歌chrome" aria-label="Permalink to &quot;5. OpenAI将发布AI浏览器挑战谷歌Chrome&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.nbcnews.com/business/business-news/openai-release-web-browser-challenge-google-chrome-rcna217818" target="_blank" rel="noreferrer">OpenAI to release web browser in challenge to Google Chrome</a></p><p><strong>一句话摘要</strong>: OpenAI即将推出AI浏览器，直接挑战谷歌Chrome的市场地位。</p><p><strong>能解决什么问题</strong>: 解决传统浏览器无法利用AI技术优化用户体验的问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过AI技术提升浏览器的搜索和浏览效率。</p><p><strong>示例场景</strong>: 用户可以直接通过AI浏览器完成网上购物等任务。</p><hr><h3 id="_6-数字-ai-23-3版本工作流概览" tabindex="-1">6. 数字.ai 23.3版本工作流概览 <a class="header-anchor" href="#_6-数字-ai-23-3版本工作流概览" aria-label="Permalink to &quot;6. 数字.ai 23.3版本工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai 23.3版本引入自助工作流简化应用上线流程。</p><p><strong>能解决什么问题</strong>: 开发者在应用上线时对工具了解不足，环境设置复杂。</p><p><strong>产品应用</strong>: 适用于需要简化云应用部署和优化的应用开发团队。</p><p><strong>示例场景</strong>: 开发者使用工作流自动化CI/CD流程，提升效率。</p><hr><h3 id="_7-16项notion更新速览-16分钟内" tabindex="-1">7. 16项Notion更新速览（16分钟内） <a class="header-anchor" href="#_7-16项notion更新速览-16分钟内" aria-label="Permalink to &quot;7. 16项Notion更新速览（16分钟内）&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=GnonRPjbzZY" target="_blank" rel="noreferrer">16 New Notion Updates (in just 16 minutes)</a></p><p><strong>一句话摘要</strong>: Notion新增16项功能，提升工作效率。</p><p><strong>能解决什么问题</strong>: 解决团队协作、信息管理、历史追踪等问题。</p><p><strong>产品应用</strong>: 适用于需要高效协作和信息管理的实际产品中。</p><p><strong>示例场景</strong>: 团队通过Notion AI追踪项目变更历史。</p><hr><h3 id="_8-notion重大更新-ai学会使用notion" tabindex="-1">8. Notion重大更新：AI学会使用Notion <a class="header-anchor" href="#_8-notion重大更新-ai学会使用notion" aria-label="Permalink to &quot;8. Notion重大更新：AI学会使用Notion&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=N3Az0b9CTMc" target="_blank" rel="noreferrer">they actually did it… (new notion update!)</a></p><p><strong>一句话摘要</strong>: Notion AI能控制工作空间并执行操作</p><p><strong>能解决什么问题</strong>: 解决数据整理和信息检索的复杂性</p><p><strong>产品应用</strong>: 可以应用，通过AI自动化数据库管理与信息检索</p><p><strong>示例场景</strong>: 自动创建数据库并从PDF中提取数据</p><hr><h3 id="_9-产品副驾驶-–-软件产品团队的ai助手" tabindex="-1">9. 产品副驾驶 – 软件产品团队的AI助手 <a class="header-anchor" href="#_9-产品副驾驶-–-软件产品团队的ai助手" aria-label="Permalink to &quot;9. 产品副驾驶 – 软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，帮助产品管理。</p><p><strong>能解决什么问题</strong>: 解决产品团队在任务管理、协作和文档更新中的效率和一致性问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过集成到现有工具中提高工作效率。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot优化产品待办事项管理。</p><hr><h3 id="_10-微软copilot-组织使用的ai工具" tabindex="-1">10. 微软Copilot | 组织使用的AI工具 <a class="header-anchor" href="#_10-微软copilot-组织使用的ai工具" aria-label="Permalink to &quot;10. 微软Copilot | 组织使用的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot提供基于聊天的生成式AI交互，助力组织和个人提升效率。</p><p><strong>能解决什么问题</strong>: 解决组织和个人在信息查询、内容创作和代码编写中的效率问题。</p><p><strong>产品应用</strong>: 可应用于企业级应用，通过集成到微软产品中，提升工作效率和安全性。</p><p><strong>示例场景</strong>: 企业员工使用Microsoft 365 Copilot快速生成报告和演示文稿。</p><hr>',75)])])}const u=t(e,[["render",s]]);export{d as __pageData,u as default};
